using System;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;
namespace Ada {
 public sealed partial class AdaWindow {
  string taskFilter="Açık";bool taskReminderExpanded;
  void SaveTaskDraft(){if(taskTitleInput!=null){taskDraftTitle=taskTitleInput.Text;taskDraftDue=taskDueInput.Text;}}
  void RebuildTasks(){SaveTaskDraft();RenderRoute(false);}
  void RenderTasks(){
   var titleRow=new DockPanel{Margin=new Thickness(0,0,0,12)};var count=Label(tools.Data.Tasks.Count(t=>!t.Done)+" açık",13,false,"Muted");count.VerticalAlignment=VerticalAlignment.Center;DockPanel.SetDock(count,Dock.Right);titleRow.Children.Add(count);titleRow.Children.Add(Label("Bugün aklında ne var?",20,true));content.Children.Add(titleRow);
   var composer=new StackPanel();var inputRow=new Grid();inputRow.ColumnDefinitions.Add(new ColumnDefinition());inputRow.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(42)});taskTitleInput=new TextBox{Text=taskDraftTitle,MinHeight=38,Padding=new Thickness(10,8,10,8),VerticalContentAlignment=VerticalAlignment.Center,BorderThickness=new Thickness(0),Background=Brushes.Transparent};System.Windows.Automation.AutomationProperties.SetName(taskTitleInput,"Görev başlığı");
   taskDueInput=new TextBox{Text=taskDraftDue,MinHeight=36,ToolTip="18:30 veya 27.10.2026 18:30",VerticalContentAlignment=VerticalAlignment.Center};System.Windows.Automation.AutomationProperties.SetName(taskDueInput,"Hatırlatma zamanı");if(editingTask!=null){var task=tools.Data.Tasks.FirstOrDefault(t=>t.Id==editingTask);if(task!=null){taskTitleInput.Text=task.Title;taskDueInput.Text=task.DueUtc>0?new DateTimeOffset(task.DueUtc,TimeSpan.Zero).ToLocalTime().ToString("dd.MM.yyyy HH:mm"):"";taskReminderExpanded=task.DueUtc>0;}}
   var inputHost=new Grid();inputHost.Children.Add(taskTitleInput);var placeholder=Label("Yeni bir görev yaz…",14,false,"Muted");placeholder.Margin=new Thickness(10,0,0,0);placeholder.VerticalAlignment=VerticalAlignment.Center;placeholder.IsHitTestVisible=false;placeholder.Visibility=taskTitleInput.Text.Length==0?Visibility.Visible:Visibility.Collapsed;inputHost.Children.Add(placeholder);taskTitleInput.TextChanged+=delegate{placeholder.Visibility=taskTitleInput.Text.Length==0?Visibility.Visible:Visibility.Collapsed;};inputRow.Children.Add(inputHost);var add=IconButton(editingTask==null?"Görev ekle":"Değişikliği kaydet",editingTask==null?"add":"check",CommitTask);add.Width=36;add.MinHeight=36;add.Padding=new Thickness(7);add.Background=(Brush)Resources["Action"];PrimaryInk(add);Grid.SetColumn(add,1);inputRow.Children.Add(add);composer.Children.Add(inputRow);
   var options=new DockPanel{Margin=new Thickness(0,5,0,0)};var reminder=ActionButton(taskReminderExpanded?"Hatırlatmayı gizle":"Hatırlatma ekle","bell",delegate{SaveTaskDraft();taskReminderExpanded=!taskReminderExpanded;RenderRoute(false);});reminder.MinHeight=30;reminder.Padding=new Thickness(7,4,7,4);reminder.Background=Brushes.Transparent;options.Children.Add(reminder);if(editingTask!=null){var cancel=ActionButton("Vazgeç","close",delegate{editingTask=null;taskDraftTitle=taskDraftDue="";taskReminderExpanded=false;RenderRoute(false);});cancel.MinHeight=30;cancel.Padding=new Thickness(7,4,7,4);cancel.Background=Brushes.Transparent;DockPanel.SetDock(cancel,Dock.Right);options.Children.Add(cancel);}composer.Children.Add(options);
   var schedule=new StackPanel{Margin=new Thickness(8,6,8,0),Visibility=taskReminderExpanded||taskDueInput.Text.Length>0?Visibility.Visible:Visibility.Collapsed};schedule.Children.Add(Label("Saat veya tarih · ör. 18:30",12,false,"Muted"));taskDueInput.Margin=new Thickness(0,5,0,0);schedule.Children.Add(taskDueInput);composer.Children.Add(schedule);var box=Card(composer);box.Padding=new Thickness(8);content.Children.Add(box);taskTitleInput.KeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Enter){CommitTask();e.Handled=true;}};
   var filters=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,0,10)};foreach(var filter in new[]{"Açık","Tamamlanan","Tümü"}){string f=filter;var b=MakeButton(f,f,delegate{taskFilter=f;RebuildTasks();});b.MinHeight=30;b.Padding=new Thickness(12,5,12,5);b.Margin=new Thickness(0,0,6,0);b.Background=(Brush)Resources[taskFilter==f?"Selected":"Nav"];filters.Children.Add(b);}content.Children.Add(filters);
   if(removedTask!=null){var undo=ActionButton("Kaldırılanı geri al","undo",delegate{tools.Data.Tasks.Add(removedTask);removedTask=null;tools.Save();RebuildTasks();});undo.MinHeight=30;undo.Margin=new Thickness(0,0,0,8);content.Children.Add(undo);}taskRows=new StackPanel();content.Children.Add(taskRows);RefreshTaskRows();
  }
  void RefreshTaskRows(){if(taskRows==null||route!="tasks")return;taskRows.Children.Clear();var tasks=tools.Data.Tasks.Where(t=>taskFilter=="Tümü"||taskFilter=="Açık"&&!t.Done||taskFilter=="Tamamlanan"&&t.Done).OrderBy(t=>t.Done).ThenBy(t=>t.DueUtc==0?Int64.MaxValue:t.DueUtc).ToArray();if(tasks.Length==0){var empty=new StackPanel{Margin=new Thickness(0,15,0,20)};empty.Children.Add(Glyph("check",28,"Muted"));var text=Label(taskFilter=="Tamamlanan"?"Tamamlanan görevler burada.":"Liste boş. İlk adımı ekle.",14,false,"Muted");text.HorizontalAlignment=HorizontalAlignment.Center;text.Margin=new Thickness(0,8,0,0);empty.Children.Add(text);taskRows.Children.Add(empty);return;}
   foreach(var item in tasks){var task=item;var row=new Grid();foreach(double width in new[]{32.0,1,30,30})row.ColumnDefinitions.Add(new ColumnDefinition{Width=width==1?new GridLength(1,GridUnitType.Star):new GridLength(width)});var check=IconButton(task.Done?"Görevi yeniden aç":"Görevi tamamla","check",delegate{task.Done=!task.Done;tools.Save();RebuildTasks();});check.Background=Brushes.Transparent;check.BorderBrush=(Brush)Resources[task.Done?"Accent":"Track"];check.BorderThickness=new Thickness(1);check.Width=28;check.MinHeight=28;check.Padding=new Thickness(6);check.Opacity=task.Done?1:.6;row.Children.Add(check);
    var labels=new StackPanel{Margin=new Thickness(9,3,8,3),VerticalAlignment=VerticalAlignment.Center};var name=Label(task.Title,14,true,task.Done?"Muted":"Text");name.TextWrapping=TextWrapping.Wrap;name.TextTrimming=TextTrimming.None;if(task.Done)name.TextDecorations=TextDecorations.Strikethrough;labels.Children.Add(name);if(task.DueUtc>0){var due=Label(new DateTimeOffset(task.DueUtc,TimeSpan.Zero).ToLocalTime().ToString("d MMM · HH:mm",tr)+(task.Notified?" · hatırlatıldı":""),12,false,"Muted");due.Margin=new Thickness(0,4,0,0);labels.Children.Add(due);}Grid.SetColumn(labels,1);row.Children.Add(labels);
    var edit=IconButton("Görevi düzenle","edit",delegate{SaveTaskDraft();editingTask=task.Id;RenderRoute(false);taskTitleInput.Focus();});edit.Width=28;edit.MinHeight=30;edit.Padding=new Thickness(6);edit.Background=Brushes.Transparent;Grid.SetColumn(edit,2);row.Children.Add(edit);var remove=IconButton("Görevi kaldır","delete",delegate{removedTask=task;tools.Data.Tasks.Remove(task);if(editingTask==task.Id)editingTask=null;tools.Save();RebuildTasks();});remove.Width=28;remove.MinHeight=30;remove.Padding=new Thickness(6);remove.Background=Brushes.Transparent;Grid.SetColumn(remove,3);row.Children.Add(remove);var card=Card(row);card.Padding=new Thickness(8,10,8,10);card.Margin=new Thickness(0,0,0,7);taskRows.Children.Add(card);
   }
  }
 }
